CREATE DATABASE IF NOT EXISTS `duty_guard` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `duty_guard`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `dictionary`;
CREATE TABLE `dictionary` (
  `id` int NOT NULL,
  `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stationId` int DEFAULT NULL,
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`,`type`),
  KEY `idx_dict_type_active` (`type`,`isActive`,`sortOrder`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `districts`;
CREATE TABLE `districts` (
  `id` int NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `export_history`;
CREATE TABLE `export_history` (
  `id` int NOT NULL,
  `fileName` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fileSize` bigint NOT NULL,
  `filePath` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year` int NOT NULL,
  `month` int NOT NULL,
  `stationId` int DEFAULT NULL,
  `operatorId` int NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `errorMessage` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_export_created` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `items`;
CREATE TABLE `items` (
  `id` int NOT NULL,
  `recordId` int NOT NULL,
  `businessType` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `content` text COLLATE utf8mb4_unicode_ci,
  `acceptTime` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `endTime` varchar(5) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerName` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerPhone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerAddress` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handler` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `result` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isCompleted` tinyint(1) NOT NULL DEFAULT '0',
  `sortOrder` int NOT NULL DEFAULT '0',
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_items_record` (`recordId`,`sortOrder`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `operation_logs`;
CREATE TABLE `operation_logs` (
  `id` int NOT NULL,
  `userId` int DEFAULT NULL,
  `username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetType` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `targetId` int DEFAULT NULL,
  `ipAddress` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userAgent` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `details` text COLLATE utf8mb4_unicode_ci,
  `statusCode` int DEFAULT NULL,
  `durationMs` int DEFAULT NULL,
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_logs_created` (`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `records`;
CREATE TABLE `records` (
  `id` int NOT NULL,
  `recordDate` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stationId` int NOT NULL,
  `weather` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `weatherLabel` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `creatorId` int NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `itemCount` int NOT NULL DEFAULT '0',
  `completedCount` int NOT NULL DEFAULT '0',
  `hasPending` tinyint(1) NOT NULL DEFAULT '0',
  `otherMatters` text COLLATE utf8mb4_unicode_ci,
  `pendingIssues` text COLLATE utf8mb4_unicode_ci,
  `lockedAt` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lockedBy` int DEFAULT NULL,
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_records_station_date` (`stationId`,`recordDate`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `refresh_tokens`;
CREATE TABLE `refresh_tokens` (
  `userId` int NOT NULL,
  `token` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiresAt` bigint NOT NULL,
  PRIMARY KEY (`userId`),
  KEY `idx_tokens_expires` (`expiresAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `stations`;
CREATE TABLE `stations` (
  `id` int NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `districtId` int NOT NULL DEFAULT '1',
  `region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `voltage` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `feeders` int NOT NULL DEFAULT '0',
  `transformers` int NOT NULL DEFAULT '0',
  `maxDutyItemsPerRecord` int NOT NULL DEFAULT '11',
  `orderTimeLimit` int NOT NULL DEFAULT '45',
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_stations_district` (`districtId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `system_configs`;
CREATE TABLE `system_configs` (
  `configKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `configValue` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updatedBy` int DEFAULT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`configKey`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int NOT NULL,
  `username` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `passwordHash` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `realName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stationId` int DEFAULT NULL,
  `districtId` int DEFAULT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `lastLoginAt` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lastLoginIp` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `updatedAt` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_username` (`username`),
  KEY `idx_users_station` (`stationId`),
  KEY `idx_users_district` (`districtId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SET FOREIGN_KEY_CHECKS = 1;
